INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66711996', 66711996, 'analyze_legacy', 'Provinsi Kalimantan Utara', 'provinsi', 'Dinas Pekerjaan Umum, Penataan Ruang, Perumahan dan Kawasan Permukiman', 'Pengawasan Pembangunan Tanggul Pengendali Banjir Tanjung Buka SP. 7 Kab. Bulungan Tahap IV', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Kalimantan Utara, Bulungan (Kab.)', 100000000, 'April 2026', 'APBD', 1, 1, '1 Paket', 'a.Tahap Persiapan, paling sedikit: 1) Memproses perizinan, memobilisasi personel dan kelengkapan yang diperlukan dalam pelaksanaan pengawasan; 2) Memeriksa, mengevaluasi dan mempelajari dokumen Kerangka Acuan Kerja (KAK) kegiatan Pengawasan dan dokumen penerapan Sistem Manajemen Keselamatan Konstruksi (SMKK); 3) Menyusun Program Mutu Pengawasan; dan 4) Memberikan penjelasan dan rekomendasi terkait pelaksanaan pekerjaan konstruksi dalam Rapat Persiapan Pelaksanaan Pekerjaan. b. Tahap Pelaksanaan, paling sedikit: 1) Melakukan pengawasan mobilisasi personel, peralatan, material dan pemenuhan persyaratan perizinan pelaksanaan pekerjaan konstruksi; 2) Melakukan reviu terhadap gambar kerja dan spesifikasinya; 3) Memberikan rekomendasi kepada direksi teknis terhadap perubahan-perubahan pelaksanaan pekerjaan; 4) Melakukan pengawasan penggunaan tenaga kerja, material, dan peralatan serta penerapan metode pelaksanaan pekerjaan konstruksi; 5) Melakukan pengawasan ketepatan waktu, biaya, pemenuhan persyaratan mutu dan volume serta penerapan keselamatan konstruksi; 6) Mengumpulkan data dan informasi di lapangan untuk memberikan rekomendasi teknis tentang alternatif pemecahan masalah yang terjadi selama pekerjaan konstruksi; 7) Membantu PPK dalam mempersiapkan penyelenggaraan rapat lapangan secara berkala dan merekomendasikan rapat insidental; 8) Membantu PPK dalam menyusunan berita acara persetujuan kemajuan pekerjaan; 9) Membuat catatan harian, menyusun laporan mingguan dan bulanan pelaksanaan pekerjaan pengawasan; 10) Melakukan koordinasi berjenjang dilapangan dengan pengawas lapangan maupun PPTK terkait pelaksanaan teknis maupun administrasi lapangan. c. Tahap Serah Terima Pertama (Provisional Hand Over), paling sedikit: 1) Menyusun daftar cacat mutu dan mengawasi perbaikannya sebelum serah terima pertama (provisional hand over); 2) Memeriksa dan melakukan evaluasi terhadap kelengkapan dokumen dan gambar as built sesuai dengan pelaksanaan pekerjaan di lapangan sebelum serah terima pertama (provisional hand over); 3) Melakukan pengawasan demobilisasi personel dan peralatan sesuai jadwal penugasan dan jadwal mobilisasi; 4) Membantu penyusunan Berita Acara Pekerjaan 100% (seratus persen) sebelum serah terima pertama (provisional hand over); 5) Membantu PPK dalam menyusunan Berita Acara Serah Terima Pertama (Provisional Hand Over); dan 6) Menyusun laporan akhir kegiatan pekerjaan pengawasan. d. Tahap Serah Terima Akhir (Final Hand Over) hanya dapat dilaksanakan oleh Konsultan Pengawas apabila dinyatakan pada kontrak. e. Tugas Konsultan Pengawas Konstruksi pada Tahap Serah Terima Akhir (Final Hand Over) sebagaimana dimaksud pada hurud d, paling sedikit: 1) Melakukan pemeriksaan terhadap hasil pekerjaan pemeliharaan; dan 2) Memberikan rekomendasi kepada PPK terkait penerbitan Berita Acara Serah Terima Akhir (Final Hand Over). f. Wewenang Konsultan Pengawas Konstruksi, meliputi: a. Pemberian persetujuan izin kerja (request of work) atas rencana pelaksanaan pekerjaan yang telah memenuhi persyaratan; dan/atau b. Pemberian rekomendasi kepada PPK untuk menghentikan setiap pekerjaan di lapangan yang tidak sesuai dengan dokumen kontrak dan dokumen SMKK.', '- Penyediaan Personel Supervision Engineer, Quantity Engineer, Inspector dan Administrasi: - Pemenuhan administrasi non-personil yang tercantum dalam kontrak pengawasan jasa konsultansi; - Tugas yang dilaksanakan oleh konsultan pengawas harus berpedoman pada ketentuan yang berlaku, serta Gambar Kerja, Perincian Penawaran, Rencana Kerja dan Syarat-Syarat, Spesifikasi Teknik yang merupakan satu kesatuan yang tidak terpisahkan dengan Kontrak Jasa Konstruksi', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2952499);
