INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66708821', 66708821, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Konsultan Asisten Manajer Bidang Monitoring Dan Evaluasi Pilar Pembangunan Lingkungan Pusat dan Daerah Regional 3, Kegiatan Koordinasi Strategis Pelaksanaan Tujuan Pembangunan Berkelanjutan/Sustainable Development Goals (TPB/SDGS) Tahun Anggaran 2026', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 180000000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Pengadaan Jasa Konsultan Asisten Manajer Bidang Monitoring dan Evaluasi yang menangani Pilar Pembangunan Lingkungan di tingkat Pusat dan Daerah Regional 3 (Jawa Barat, Sulawesi Utara, Sulawesi Tengah, Sulawesi Selatan, Sulawesi Tenggara, Gorontalo, Sulawesi Barat, Maluku, dan Maluku Utara) dilakukan dengan tujuan untuk membantu pelaksanaan Koordinasi Strategis Pelaksanaan Tujuan Pembangunan Berkelanjutan/Sustainable Development Goals (TPB/SDGs) Tahun 2026 khususnya bidang monitoring dan evaluasi.', 'Adapun ruang lingkup pekerjaan untuk Jasa Konsultan Asisten Manajer Bidang Monitoring dan Evaluasi yang menangani Pilar Pembangunan Lingkungan di tingkat Pusat dan Daerah Regional 3 (Jawa Barat, Sulawesi Utara, Sulawesi Tengah, Sulawesi Selatan, Sulawesi Tenggara, Gorontalo, Sulawesi Barat, Maluku, dan Maluku Utara) adalah: Pengelolaan data dan pemutakhiran pada sistem database dan monitoring dan evaluasi, dan laporan pelaksanaan TPB/SDGs pemerintah dan non pemerintah pilar pembangunan lingkungan di tingkat pusat dan daerah regional 3; Penginputan, penyimpanan, dan pemutakhiran data monitoring dan evaluasi dari kementerian/lembaga dan nonpemerintah pilar pembangunan lingkungan di tingkat pusat dan daerah regional 3; Koordinasi dan komunikasi komunikasi secara intensif dengan para pemangku kepentingan untuk pelaksanaan pemantauan dan evaluasi serta pengumpulan data TPB/SDGs pilar pembangunan lingkungan baik di tingkat pusat maupun daerah regional 3 untuk menjamin pelaporan dan pemantauan TPB/SDGs secara reguler; Peningkatan kapasitas pemantauan dan evaluasi TPB/SDGs pemangku kepentingan pilar pembangunan lingkungan di tingkat pusat dan daerah regional 3; Fasilitasi dalam rangka pelaksanaan monitoring dan evaluasi kegiatan TPB/SDGs pilar pembangunan lingkungan di tingkat pusat dan daerah regional 3; Pengembangan tampilan data dan informasi hasil pemantauan dan evaluasi pilar pembangunan lingkungan baik dalam dashboard, maupun tampilan lainnya; Analisis awal dan penyusunan draf awal umpan balik laporan pemantauan dan evaluasi TPB/SDGs pilar pembangunan lingkungan tingkat pusat dan daerah regional 3 baik pemerintah maupun non-pemerintah; Penyusunan draf awal laporan pemantauan dan capaian pelaksanaan TPB/SDG pilar pembangunan lingkungan yang mencakup pusat dan Daerah Regional 3; Penyiapan data evaluasi capaian pelaksanaan TPB/SDGs pilar pembangunan lingkungan yang mencakup pusat dan Daerah Regional 3; Review dan analisis laporan pemantauan dan evaluasi pelaksanaan TPB/SDGs di tingkat provinsi daerah regional 3 (monitoring dan evaluasi terhadap RAD provinsi); Koordinasi dengan tim pilar dan bidang lainnya dalam Sekretariat TPB/SDGs dan dengan Manajer Monitoring dan Evaluasi; Penyampaian informasi dan laporan yang baik dan tepat waktu kepada Manajer Monitoring dan Evaluasi dan Koordinator Tim Ahli Sekretariat Nasional SDGs; dan Pelaksanaan tugas-tugas lainnya untuk kepentingan pelaksanaan kegiatan Koordinasi Strategis Pelaksanaan Tujuan Pembangunan Berkelanjutan/Sustainable Development Goals (SDGs).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2953151);
