INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66710138', 66710138, 'analyze_legacy', 'Provinsi Kalimantan Utara', 'provinsi', 'Dinas Pekerjaan Umum, Penataan Ruang, Perumahan dan Kawasan Permukiman', 'Pembangunan Tanggul Pengendali Banjir Tanjung Buka SP. 7 Kab. Bulungan Tahap IV', 'Pekerjaan Konstruksi', 'E-Purchasing', 'Kalimantan Utara, Bulungan (Kab.)', 3839760000, 'April 2026', 'APBD', 1, 1, '1 Paket', '1. Pekerjaan persiapan a. Mobilisasi dan demobilisasi alat 1 Ls b. Papan Nama Proyek 1 Buah 2. Pekerjaan Tanggul Tanah a. Pekerjaan badan tanggul tanah 71.540 m3 b. Pipa PVC 6\'\' sebanyak 400 meter 3. Sistem Manajemen Keselamatan Konstruksi a. Pembuatan dokumen SMKK 1 set b. Pembuatan Prosedur dan instruksi kerja 1 set c. Penyusunan pelaporan penerapan SMKK 1 set d. Spanduk (Banner) 1 lembar e. Poster 1 lembar f. Papan Informasi Keselamatan Konstruksi 1 buah g. Helm Pelindung 6 buah h. Sarung Tangan 6 pasang i. Sepatu Keselamatan 6 pasang j. Rompi Keselamatan 6 buah k. Asuransi Keselamatan 1 ls l. Petugas keselamatan konstruksi, petugas K3 Konstruksi 2 org/bulan m. Peralatan P3K 1 set n. Rambu Informasi 1 buah', '1. Diwajibkan untuk melakukan pengukuran lapangan dan membuat Shop Drawing sebelum memulai pelaksanaan pekerjaan dan diakhir pelaksanaan pekerjaan membuat As Built Drawing untuk diajukan dan disetujui oleh Pejabat Pembuat Komitmen; 2. Diwajibkan melaksanakan dan menyelesaikan pekerjaan sesuai dengan jadwal pelaksanaan pekerjaan yang telah ditetapkan sesuai spesifikasi teknis dalam kontrak; 3. Diwajibkan melaporkan pelaksanaan pekerjaan secara periodik kepada Pejabat Pembuat Komitmen; 4. Diwajibkan untuk mengikuti rapat-rapat yang ditentukan oleh Pejabat Pembuat Komitmen, seperti Pra Construction Meeting, Rapat Bulanan, Cause Meeting, dan rapat lainnya sebagai kendali pelaksanaan pekerjaan dan melaksanakan hasil rapat tersebut; 5. Memberikan keterangan yang diperlukan untuk pemeriksaan pelaksanaan yang dilakukan oleh Pejabat Pembuat Komitmen atau tim teknis yang ditugaskan oleh PPK; 6. Diwajibkan menyerahkan hasil pekerjaan sesuai dengan jadwal penyerahan pekerjaan yang telah ditetapkan dalam kontrak; 7. Mengambil langkah-langkah yang memadai untuk melindungi lingkungan baik di dalam maupun di luar tempat kerja dan membatasi perusakan dan pengaruh/gangguan kepada masyarakat maupun miliknya, sebagai akibat polusi, kebisingan dan kerusakan lain yang disebabkan kegiatan penyedia jasa; 8. Seluruh kegiatan dalam pelaksanaan pekerjaan di lapangan harus didokumentasikan dengan foto-foto asli yang dilampirkan dalam laporan hasil pekerjaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2954719);
